insert into public.training_scenarios_v22(stable_key,title,scenario_type,role_focus,intro,prompt,decisions,debrief,visuals,media,sources) values
('v22:eq-cmm','CMM: stabilità, materiale e zone cieche','hazard_spotting','operatore CMM','Il caricatore deve movimentare materiale su terreno non perfettamente uniforme, con persone e veicoli che possono entrare nel raggio operativo.','Prima della presa, individua portanza, pendenza, visibilità, caratteristiche del materiale, accessorio installato e percorso del carico.','[{"choice":"Riduco velocità, definisco zona esclusa e verifico stabilità/accessorio prima della presa","effect":"Movimentazione governata"},{"choice":"Compenso con esperienza e procedo finché il mezzo risponde","effect":"Margine di stabilità non controllato"}]'::jsonb,'{"questions":["Che cosa cambia con materiale irregolare?","Quali sono le zone cieche?","Quando terreno o pendenza impongono stop?"]}'::jsonb,'[{"asset":"idea-inspection-flow.svg"},{"asset":"piramide-pericoli.svg"}]'::jsonb,'[{"kind":"reference","title":"INAIL - attrezzature di lavoro e formazione operatori","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/attrezzature-di-lavoro/informazione%2C-formazione-e-addestramento.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/attrezzature-di-lavoro/informazione%2C-formazione-e-addestramento.html"}]'::jsonb),
('v22:eq-forklift-industrial','Carrello industriale: carico, pedoni e banchina','decision','carrellista','Devi prelevare un pallet vicino a una banchina mentre pedoni attraversano il reparto e la visuale anteriore è parzialmente coperta dal carico.','Organizza percorso, altezza forche, velocità, comunicazione e separazione pedoni prima di muoverti.','[{"choice":"Segrego il percorso e viaggio con carico in posizione compatibile con visibilità e stabilità","effect":"Riduzione investimento/ribaltamento"},{"choice":"Uso il clacson e continuo anche con pedoni nel percorso","effect":"Controllo insufficiente"}]'::jsonb,'{"questions":["Come cambia la guida con visuale coperta?","Qual è il rischio al bordo banchina?","Quando va usato un segnalatore?"]}'::jsonb,'[{"asset":"idea-inspection-flow.svg"},{"asset":"idea-road-safety.svg"}]'::jsonb,'[{"kind":"reference","title":"INAIL - corso operatori attrezzature","url":"https://www.inail.it/portale/formazione/it/corsi-inail/catalogo-corsi/dettaglio-corso.2024.01.corso-di-formazione-per-l-abilitazione-degli-operatori-delle-attrezzature.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/formazione/it/corsi-inail/catalogo-corsi/dettaglio-corso.2024.01.corso-di-formazione-per-l-abilitazione-degli-operatori-delle-attrezzature.html"}]'::jsonb),
('v22:eq-forklift-all','Carrelli telescopici e rotativi: configurazione e diagramma di carico','decision','operatore carrelli','L’accessorio e lo sbraccio richiesti cambiano rispetto alla configurazione abituale.','Verifica identificazione dell’accessorio, diagramma di carico, stabilizzazione, terreno, raggio e persone prima della manovra.','[{"choice":"Ricalcolo la configurazione operativa sul diagramma corretto e imposto zona esclusa","effect":"Limiti macchina rispettati"},{"choice":"Uso la capacità nominale generale del mezzo","effect":"Capacità reale sovrastimata"}]'::jsonb,'{"questions":["Perché l’accessorio cambia la capacità?","Che cosa verifica il diagramma?","Come cambia la zona per un rotativo?"]}'::jsonb,'[{"asset":"idea-inspection-flow.svg"},{"asset":"piramide-pericoli.svg"}]'::jsonb,'[{"kind":"reference","title":"INAIL - attrezzature marcate CE","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/attrezzature-di-lavoro/attrezzature-marcate-CE.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/attrezzature-di-lavoro/attrezzature-marcate-CE.html"}]'::jsonb),
('v22:eq-overhead-crane','Carroponte: imbracatura, percorso del carico e comunicazione','decision','operatore carroponte','Un carico asimmetrico deve attraversare una zona dove lavorano altre persone.','Definisci massa/centro di gravità, accessori di sollevamento, prova di tensionamento, percorso e segnalatore prima del sollevamento.','[{"choice":"Faccio prova a bassa quota, sgombero il percorso e uso segnali concordati","effect":"Carico controllato"},{"choice":"Sollevo subito e chiedo alle persone di spostarsi durante il passaggio","effect":"Persone esposte al carico sospeso"}]'::jsonb,'{"questions":["Come riconosci un carico instabile?","Chi può stare sotto il carico?","Quando interrompi per comunicazione ambigua?"]}'::jsonb,'[{"asset":"idea-inspection-flow.svg"},{"asset":"stop-segnala-ripristina.svg"}]'::jsonb,'[{"kind":"reference","title":"INAIL - attrezzature di lavoro","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/attrezzature-di-lavoro.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/attrezzature-di-lavoro.html"}]'::jsonb),
('v22:eq-tower-crane','Gru a torre: vento, interferenze e percorso del carico','tabletop','gruista','Il cantiere è congestionato, il vento aumenta e il percorso del carico incrocia aree operative.','Decidi se e come sollevare valutando limiti meteo, comunicazione, anti-collisione/interferenze, imbracatura e zona sottostante.','[{"choice":"Rivaluto meteo e interferenze e sospendo se i limiti non sono garantiti","effect":"Sollevamento autorizzato solo in condizioni controllate"},{"choice":"Accelero il ciclo per finire prima che il vento aumenti","effect":"Pressione produttiva aumenta il rischio"}]'::jsonb,'{"questions":["Quale dato meteo conta?","Chi controlla la zona sottostante?","Come gestisci segnale perso?"]}'::jsonb,'[{"asset":"idea-inspection-flow.svg"},{"asset":"idea-working-height-safe.svg"}]'::jsonb,'[{"kind":"reference","title":"INAIL - corso operatori attrezzature","url":"https://www.inail.it/portale/formazione/it/corsi-inail/catalogo-corsi/dettaglio-corso.2024.01.corso-di-formazione-per-l-abilitazione-degli-operatori-delle-attrezzature.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/formazione/it/corsi-inail/catalogo-corsi/dettaglio-corso.2024.01.corso-di-formazione-per-l-abilitazione-degli-operatori-delle-attrezzature.html"}]'::jsonb),
('v22:eq-truck-crane','Gru per autocarro: stabilizzatori, terreno e linee aeree','hazard_spotting','operatore gru per autocarro','Devi scaricare vicino a un bordo strada con terreno eterogeneo e una linea elettrica nell’area.','Definisci area, portanza, stabilizzatori, distanze, diagramma di carico e comunicazione prima di estendere il braccio.','[{"choice":"Verifico portanza/appoggi e mantengo l’operazione fuori dalle condizioni elettriche non controllate","effect":"Setup sicuro"},{"choice":"Uso piastre più grandi senza rivalutare tutto il piano","effect":"Una sola misura non risolve il quadro"}]'::jsonb,'{"questions":["Come verifichi gli appoggi?","Che cosa cambia vicino a linee aeree?","Quando il diagramma vieta la manovra?"]}'::jsonb,'[{"asset":"idea-inspection-flow.svg"},{"asset":"idea-road-safety.svg"}]'::jsonb,'[{"kind":"reference","title":"INAIL - corso operatori attrezzature","url":"https://www.inail.it/portale/formazione/it/corsi-inail/catalogo-corsi/dettaglio-corso.2024.01.corso-di-formazione-per-l-abilitazione-degli-operatori-delle-attrezzature.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/formazione/it/corsi-inail/catalogo-corsi/dettaglio-corso.2024.01.corso-di-formazione-per-l-abilitazione-degli-operatori-delle-attrezzature.html"}]'::jsonb),
('v22:eq-crf','Raccoglifrutta CRF: terreno, piattaforma e ostacoli in quota','hazard_spotting','operatore CRF','Il filare ha irregolarità, rami sporgenti e passaggi stretti; la raccolta richiede frequenti spostamenti.','Valuta terreno, stabilità, protezioni della piattaforma, ostacoli, persone e modalità di trasferimento prima di lavorare in quota.','[{"choice":"Adeguo percorso e modalità ai limiti del mezzo e tengo la zona controllata","effect":"Stabilità e intrappolamento gestiti"},{"choice":"Compenso le irregolarità con movimenti più lenti senza cambiare percorso","effect":"Condizione del terreno non eliminata"}]'::jsonb,'{"questions":["Quali ostacoli possono intrappolare l’operatore?","Quando il terreno impone una deviazione?","Cosa controlli sulle protezioni della piattaforma?"]}'::jsonb,'[{"asset":"idea-green-safearea.svg"},{"asset":"idea-working-height-safe.svg"}]'::jsonb,'[{"kind":"reference","title":"INAIL - ricerca sicurezza in agricoltura","url":"https://www.inail.it/portale/ricerca-e-tecnologia/it/ambiti-di-ricerca/area-sicurezza-sul-lavoro/agricoltura.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/ricerca-e-tecnologia/it/ambiti-di-ricerca/area-sicurezza-sul-lavoro/agricoltura.html"}]'::jsonb),
('v22:eq-mmt-all','Macchine movimento terra: terreno, bordo scavo e interferenze','hazard_spotting','operatore MMT','Escavatore, pala e terna condividono una zona con scavi, mezzi di trasporto e personale a terra.','Costruisci il piano di movimento: terreno, bordi, raggi di rotazione, retromarcia, segnalatore, accessori e separazione delle persone.','[{"choice":"Separo flussi, definisco distanze dal bordo e segnali prima della manovra","effect":"Interferenze controllate"},{"choice":"Affido al contatto visivo tra operatori il coordinamento","effect":"Zone cieche e comunicazioni restano critiche"}]'::jsonb,'{"questions":["Come cambia il rischio vicino allo scavo?","Dove non può stare un pedone?","Quando serve un segnalatore dedicato?"]}'::jsonb,'[{"asset":"idea-inspection-flow.svg"},{"asset":"idea-road-safety.svg"}]'::jsonb,'[{"kind":"reference","title":"INAIL - macchine per cantiere e costruzioni","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/attrezzature-di-lavoro/attrezzature-marcate-CE.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/attrezzature-di-lavoro/attrezzature-marcate-CE.html"}]'::jsonb),
('v22:eq-excavator','Escavatore: scavo, servizi interrati e raggio di rotazione','decision','operatore escavatore','Devi iniziare uno scavo vicino a una viabilità interna e a sottoservizi indicati solo parzialmente.','Prima di scavare, verifica localizzazione servizi, distanza dal bordo, stabilità, raggio posteriore, persone e modalità di carico.','[{"choice":"Fermo l’avvio finché sottoservizi e zona operativa non sono chiariti","effect":"Evita scavo alla cieca"},{"choice":"Procedo con piccoli assaggi perché il rischio sembra basso","effect":"Possibile contatto con sottoservizi"}]'::jsonb,'{"questions":["Quali informazioni devono esserci prima dello scavo?","Chi può entrare nel raggio di rotazione?","Come posizioni il mezzo rispetto al bordo?"]}'::jsonb,'[{"asset":"idea-inspection-flow.svg"},{"asset":"stop-segnala-ripristina.svg"}]'::jsonb,'[{"kind":"reference","title":"INAIL - macchine per cantiere e costruzioni","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/attrezzature-di-lavoro/attrezzature-marcate-CE.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/attrezzature-di-lavoro/attrezzature-marcate-CE.html"}]'::jsonb),
('v22:eq-ple','PLE: stabilità, schiacciamento e recupero operatore','decision','operatore PLE','La piattaforma deve raggiungere un punto sotto una struttura con ostacoli sopra la cesta e spazio limitato alla base.','Decidi posizionamento, stabilizzazione, percorso della cesta, controllo ostacoli, uso dei sistemi previsti e piano di recupero.','[{"choice":"Riposiziono per evitare la zona di intrappolamento e verifico recupero da terra","effect":"Schiacciamento prevenuto"},{"choice":"Procedo molto lentamente vicino all’ostacolo","effect":"Velocità ridotta non elimina l’intrappolamento"}]'::jsonb,'{"questions":["Dove sono i punti di intrappolamento?","Chi sa usare i comandi di emergenza a terra?","Come cambia il piano con stabilizzatori?"]}'::jsonb,'[{"asset":"idea-working-height-safe.svg"},{"asset":"idea-inspection-flow.svg"}]'::jsonb,'[{"kind":"reference","title":"INAIL - Piattaforme di lavoro elevabili","url":"https://www.inail.it/content/dam/inail-hub-site/documenti/2024/05/PiattaformeDiLavoroElevabili.pdf"},{"kind":"reference","title":"INAIL - realtà aumentata per sicurezza PLE","url":"https://www.inail.it/portale/it/inail-comunica/eventi/evento.2023.05.seminario-la-realt-aumentata-per-la-sicurezza-delle-piattaforme-di-lavoro-elevabili-.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/content/dam/inail-hub-site/documenti/2024/05/PiattaformeDiLavoroElevabili.pdf"}]'::jsonb),
('v22:eq-concrete-pump','Pompa calcestruzzo: stabilizzazione, linea e tubo terminale','hazard_spotting','operatore pompa calcestruzzo','Il getto richiede braccio esteso, area ridotta e tubo terminale vicino a più lavoratori.','Valuta appoggi, linea elettrica, percorso del braccio, tubazione, collegamenti, area del tubo terminale e comunicazione prima del pompaggio.','[{"choice":"Segrego il tubo terminale e verifico appoggi/linea prima di pressurizzare","effect":"Controllo di colpi di frusta e stabilità"},{"choice":"Mantengo personale vicino per guidare meglio il tubo","effect":"Persone esposte a movimento improvviso"}]'::jsonb,'{"questions":["Cosa succede in caso di blocco?","Dove non devono stare le persone?","Quando fermare il pompaggio?"]}'::jsonb,'[{"asset":"idea-inspection-flow.svg"},{"asset":"procedura-operativa-5-fasi.svg"}]'::jsonb,'[{"kind":"reference","title":"INAIL - attrezzature e macchine per cantiere","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/attrezzature-di-lavoro/attrezzature-marcate-CE.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/attrezzature-di-lavoro/attrezzature-marcate-CE.html"}]'::jsonb),
('v22:eq-tractor','Trattore: ribaltamento, ROPS, cintura e PTO','decision','operatore trattore','La lavorazione si svolge su terreno inclinato con attrezzatura collegata e frequenti salite/discese dal mezzo.','Valuta pendenza, terreno, ROPS/cabina, cintura, collegamento attrezzo, PTO, passeggeri e percorso prima della partenza.','[{"choice":"Adatto percorso e lavoro ai limiti di stabilità e uso ROPS/cintura come sistema","effect":"Protezione dal ribaltamento coerente"},{"choice":"Tengo velocità bassa e lascio la cintura libera per scendere più rapidamente","effect":"Sistema ROPS incompleto senza ritenuta"}]'::jsonb,'{"questions":["Perché ROPS e cintura lavorano insieme?","Quando la pendenza impone un altro percorso?","Come gestisci la PTO prima di intervenire?"]}'::jsonb,'[{"asset":"idea-green-safearea.svg"},{"asset":"idea-inspection-flow.svg"}]'::jsonb,'[{"kind":"reference","title":"INAIL - sicurezza in agricoltura","url":"https://www.inail.it/portale/ricerca-e-tecnologia/it/ambiti-di-ricerca/area-sicurezza-sul-lavoro/agricoltura.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/ricerca-e-tecnologia/it/ambiti-di-ricerca/area-sicurezza-sul-lavoro/agricoltura.html"}]'::jsonb)
on conflict(stable_key) do update set title=excluded.title,scenario_type=excluded.scenario_type,role_focus=excluded.role_focus,intro=excluded.intro,prompt=excluded.prompt,decisions=excluded.decisions,debrief=excluded.debrief,visuals=excluded.visuals,media=excluded.media,sources=excluded.sources,active=true,updated_at=now();

insert into public.practice_labs_v22(stable_key,title,lab_type,objective,briefing,steps,checklist,critical_errors,stop_conditions,media,sources,requires_physical_validation) values
('v22:eq-cmm-lab','CMM: pre-use, presa, trasporto e deposito','physical','Eseguire una sequenza completa con materiale reale/simulato mantenendo stabilità, visibilità e zona esclusa.','Usare manuale, accessorio e configurazione reali del mezzo.','["walk-around e identificazione accessorio","verifica terreno/percorso","predisponi zona esclusa","presa a bassa velocità","solleva solo quanto necessario","trasporto con assetto stabile","deposito controllato","parcheggio e isolamento"]'::jsonb,'["pre-use","accessorio","terreno","visibilità","stabilità","zona pedoni","deposito","fine uso"]'::jsonb,'["carico alto in trasferimento","sterzata brusca con carico","persone nel raggio","uso accessorio non verificato"]'::jsonb,'["allarme o difetto","stabilità dubbia","materiale non contenibile","percorso non segregabile"]'::jsonb,'[{"kind":"reference","title":"INAIL - formazione e addestramento attrezzature","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/attrezzature-di-lavoro/informazione%2C-formazione-e-addestramento.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/attrezzature-di-lavoro/informazione%2C-formazione-e-addestramento.html"}]'::jsonb,true),
('v22:eq-forklift-industrial-lab','Carrello industriale: corridoio, pallet e banchina','physical','Dimostrare controllo del carrello in marcia, presa/deposito e interazione con pedoni e banchine.','Preparare un circuito in area protetta con pallet e punti di arresto.','["pre-use","regolazione posto guida e cintura se prevista","partenza e frenata","curve e incroci","presa pallet","trasporto","deposito","retromarcia/visibilità","parcheggio"]'::jsonb,'["forche","carico","velocità","pedoni","visuale","banchina","frenata","parcheggio"]'::jsonb,'["curva veloce","forche alte in marcia","pedone nel percorso","bordo banchina non protetto"]'::jsonb,'["freno/sterzo/allarme anomalo","pallet instabile","percorso invaso","visibilità non gestibile"]'::jsonb,'[{"kind":"reference","title":"INAIL - corso operatori attrezzature","url":"https://www.inail.it/portale/formazione/it/corsi-inail/catalogo-corsi/dettaglio-corso.2024.01.corso-di-formazione-per-l-abilitazione-degli-operatori-delle-attrezzature.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/formazione/it/corsi-inail/catalogo-corsi/dettaglio-corso.2024.01.corso-di-formazione-per-l-abilitazione-degli-operatori-delle-attrezzature.html"}]'::jsonb,true),
('v22:eq-forklift-all-lab','Carrelli telescopici/rotativi: configurazione e manovra','physical','Verificare capacità nella configurazione reale e condurre una manovra con accessorio, sbraccio e stabilizzazione corretti.','Il docente prepara configurazioni diverse per mostrare come cambia la capacità.','["identifica modello/accessorio","leggi diagramma corretto","verifica terreno","stabilizza se previsto","delimita raggio","esegui presa","varia sbraccio entro limiti","deposita","rientra e parcheggia"]'::jsonb,'["diagramma","accessorio","stabilizzatori","terreno","raggio rotazione","carico","comunicazione","fine uso"]'::jsonb,'["usare capacità nominale generica","stabilizzatore su appoggio dubbio","persona nel raggio rotativo","accessorio non riconosciuto"]'::jsonb,'["configurazione fuori diagramma","appoggio cedevole","limitazione dispositivo","comunicazione persa"]'::jsonb,'[{"kind":"reference","title":"INAIL - attrezzature marcate CE","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/attrezzature-di-lavoro/attrezzature-marcate-CE.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/attrezzature-di-lavoro/attrezzature-marcate-CE.html"}]'::jsonb,true),
('v22:eq-overhead-crane-lab','Carroponte: aggancio, prova e trasferimento','physical','Eseguire un sollevamento controllato dall’identificazione del carico al deposito.','Utilizzare carico didattico e accessori identificati/idonei.','["stima/identifica massa e baricentro","scegli accessori","ispeziona gancio/accessori","aggancia","tensiona e prova a bassa quota","sgombera percorso","trasferisci senza oscillazioni","deposita e sgancia"]'::jsonb,'["massa","accessori","angoli","gancio","prova","percorso","segnali","deposito"]'::jsonb,'["nodo/imbracatura improvvisata","carico sopra persone","strappo in partenza","segnali contrastanti"]'::jsonb,'["accessorio non identificabile/danneggiato","baricentro incerto","persona nel percorso","comunicazione non univoca"]'::jsonb,'[{"kind":"reference","title":"INAIL - attrezzature di lavoro","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/attrezzature-di-lavoro.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/attrezzature-di-lavoro.html"}]'::jsonb,true),
('v22:eq-tower-crane-lab','Gru a torre: ciclo di sollevamento con segnalatore','physical','Eseguire un ciclo completo con controlli, comunicazione, percorso e arresto in anomalia.','Usare il modello reale e i limiti indicati dal fabbricante/organizzazione di cantiere.','["controlli iniziali","verifica meteo e area","briefing segnali","imbracatura","prova sollevamento","traslazione/rotazione controllata","deposito","simulazione perdita comunicazione","fine turno"]'::jsonb,'["meteo","dispositivi","segnali","carico","percorso","interferenze","stop","fine uso"]'::jsonb,'["operare con segnale ambiguo","sorvolare persone","continuare oltre limite meteo/impianto","strappare il carico"]'::jsonb,'["comunicazione persa","limite meteo","allarme dispositivo","interferenza non controllata"]'::jsonb,'[{"kind":"reference","title":"INAIL - corso operatori attrezzature","url":"https://www.inail.it/portale/formazione/it/corsi-inail/catalogo-corsi/dettaglio-corso.2024.01.corso-di-formazione-per-l-abilitazione-degli-operatori-delle-attrezzature.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/formazione/it/corsi-inail/catalogo-corsi/dettaglio-corso.2024.01.corso-di-formazione-per-l-abilitazione-degli-operatori-delle-attrezzature.html"}]'::jsonb,true),
('v22:eq-truck-crane-lab','Gru autocarro: setup, stabilizzazione e scarico','physical','Allestire l’autocarro e completare una manovra nel rispetto di stabilità e diagramma di carico.','Preparare area con appoggi verificabili e carico didattico.','["posiziona veicolo","freno/assetto","verifica terreno e sottoservizi","apri stabilizzatori/piastre","controlla linea elettrica/ostacoli","leggi diagramma","aggancia e prova","scarica","ripiega e verifica chiusure"]'::jsonb,'["veicolo","appoggi","stabilizzatori","diagramma","linee/ostacoli","zona esclusa","comunicazione","chiusura"]'::jsonb,'["stabilizzatore parziale non previsto","appoggio su chiusino/bordo","carico fuori diagramma","persona tra mezzo e carico"]'::jsonb,'["portanza incerta","linea elettrica non gestita","stabilizzazione incompleta","allarme limitatore"]'::jsonb,'[{"kind":"reference","title":"INAIL - corso operatori attrezzature","url":"https://www.inail.it/portale/formazione/it/corsi-inail/catalogo-corsi/dettaglio-corso.2024.01.corso-di-formazione-per-l-abilitazione-degli-operatori-delle-attrezzature.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/formazione/it/corsi-inail/catalogo-corsi/dettaglio-corso.2024.01.corso-di-formazione-per-l-abilitazione-degli-operatori-delle-attrezzature.html"}]'::jsonb,true),
('v22:eq-crf-lab','CRF: filare, quota e spostamento controllato','physical','Condurre la raccoglifrutta su percorso didattico gestendo terreno, ostacoli e lavoro in piattaforma.','Il percorso deve riprodurre restringimenti e ostacoli senza creare rischi reali.','["pre-use","valuta percorso e terreno","accesso piattaforma","protezioni chiuse","elevazione controllata","avvicinamento al punto di raccolta","spostamento consentito dal modello","discesa e parcheggio"]'::jsonb,'["terreno","protezioni","ostacoli","comandi","quota","persone","emergenza","fine uso"]'::jsonb,'["sporgersi oltre protezioni","muoversi in configurazione non consentita","entrare sotto la piattaforma","ignorare ramo/ostacolo sopra cesta"]'::jsonb,'["terreno non stabile","protezione non efficiente","ostacolo non evitabile","allarme/inclinazione"]'::jsonb,'[{"kind":"reference","title":"INAIL - sicurezza in agricoltura","url":"https://www.inail.it/portale/ricerca-e-tecnologia/it/ambiti-di-ricerca/area-sicurezza-sul-lavoro/agricoltura.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/ricerca-e-tecnologia/it/ambiti-di-ricerca/area-sicurezza-sul-lavoro/agricoltura.html"}]'::jsonb,true),
('v22:eq-mmt-all-lab','MMT: circuito operativo e segregazione','physical','Condurre le principali manovre in area controllata verificando terreno, visibilità e interferenze.','Adattare il circuito alla macchina effettivamente disponibile.','["pre-use","accesso e cintura/sistemi previsti","percorso avanti/indietro","curva e posizionamento","lavoro vicino a bordo simulato","uso benna/accessorio","carico mezzo o deposito","parcheggio e abbassamento attrezzatura"]'::jsonb,'["terreno","visuale","zona rotazione","retromarcia","bordo","accessorio","segnali","parcheggio"]'::jsonb,'["pedone nella zona","benna alta in trasferimento non previsto","sosta al bordo instabile","uscita con attrezzatura sollevata"]'::jsonb,'["terreno cedevole","segnale perso","persona entra in zona","allarme macchina"]'::jsonb,'[{"kind":"reference","title":"INAIL - macchine per cantiere e costruzioni","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/attrezzature-di-lavoro/attrezzature-marcate-CE.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/attrezzature-di-lavoro/attrezzature-marcate-CE.html"}]'::jsonb,true),
('v22:eq-excavator-lab','Escavatore: scavo simulato, rotazione e carico','physical','Eseguire un ciclo di scavo e deposito mantenendo distanze, stabilità e zona libera.','Prima della prova identificare sottoservizi simulati e bordo scavo.','["pre-use","posiziona rispetto a bordo","segrega raggio di rotazione","esegui scavo controllato","ruota e deposita","carica mezzo simulato","gestisci segnale stop","parcheggia con attrezzatura a terra"]'::jsonb,'["bordo","sottoservizi","raggio","visuale","segnalatore","benna","stop","parcheggio"]'::jsonb,'["scavare senza autorizzazione sottoservizi","persona nel raggio","rotazione cieca","parcheggio con attrezzatura sospesa"]'::jsonb,'["sottoservizi incerti","bordo instabile","persona entra in zona","anomalia idraulica"]'::jsonb,'[{"kind":"reference","title":"INAIL - macchine per cantiere e costruzioni","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/attrezzature-di-lavoro/attrezzature-marcate-CE.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/attrezzature-di-lavoro/attrezzature-marcate-CE.html"}]'::jsonb,true),
('v22:eq-ple-lab','PLE: posizionamento, elevazione, ostacoli e recupero','physical','Eseguire una missione completa con controlli, elevazione, spostamento previsto ed emergenza.','Usare il modello reale; il docente prepara un ostacolo simulato che obbliga a scegliere il corretto riposizionamento.','["pre-use e documenti","valuta terreno/ostacoli","stabilizza se previsto","accesso e chiusura cesta","prova comandi","elevazione","avvicinamento senza intrappolamento","simula arresto e recupero da terra","rientra e parcheggia"]'::jsonb,'["terreno","stabilizzatori","ostacoli","cesta","comandi","intrappolamento","emergenza","fine uso"]'::jsonb,'["usare cesta come punto di sbarco non previsto","avvicinarsi a ostacolo affidandosi solo alla lentezza","nessun operatore informato sui comandi a terra"]'::jsonb,'["inclinazione/allarme","ostacolo non controllabile","recupero non disponibile","vento/condizione oltre limiti"]'::jsonb,'[{"kind":"reference","title":"INAIL - Piattaforme di lavoro elevabili","url":"https://www.inail.it/content/dam/inail-hub-site/documenti/2024/05/PiattaformeDiLavoroElevabili.pdf"},{"kind":"reference","title":"INAIL - training immersivo PLE","url":"https://www.inail.it/portale/it/inail-comunica/eventi/evento.2023.05.seminario-la-realt-aumentata-per-la-sicurezza-delle-piattaforme-di-lavoro-elevabili-.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/content/dam/inail-hub-site/documenti/2024/05/PiattaformeDiLavoroElevabili.pdf"}]'::jsonb,true),
('v22:eq-concrete-pump-lab','Pompa calcestruzzo: setup, pompaggio e gestione blocco','physical','Preparare e condurre il pompaggio riconoscendo condizioni di instabilità e sovrapressione/blocco.','La prova pratica non deve introdurre condizioni pericolose: la gestione blocco può essere simulata a impianto fermo.','["posiziona e stabilizza","segrega braccio e tubo terminale","ispeziona tubazioni/giunti","briefing segnali","avvio controllato","pompaggio","simula perdita comunicazione","simula blocco e procedura di stop","lavaggio/ripristino secondo procedura"]'::jsonb,'["appoggi","linee aeree","giunti","tubo terminale","segnali","pressione","stop","ripristino"]'::jsonb,'["aprire giunto in pressione","persona nel raggio tubo","stabilizzatore su appoggio dubbio","riavvio senza comunicazione"]'::jsonb,'["blocco non risolto con procedura prevista","perdita/giunto anomalo","appoggio instabile","persona entra in zona"]'::jsonb,'[{"kind":"reference","title":"INAIL - macchine per cantiere","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/attrezzature-di-lavoro/attrezzature-marcate-CE.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/attrezzature-di-lavoro/attrezzature-marcate-CE.html"}]'::jsonb,true),
('v22:eq-tractor-lab','Trattore: percorso, attrezzo, pendenza e PTO','physical','Condurre il trattore con attrezzo in un percorso che richiede scelta di rapporto, velocità e traiettoria sicura.','Usare ROPS/cabina, sistemi di ritenuta e attrezzatura compatibili col mezzo.','["pre-use","verifica ROPS/cintura","aggancio attrezzo a macchina ferma","percorso piano","curva","pendenza compatibile","arresto","disinnesto e messa in sicurezza PTO","parcheggio"]'::jsonb,'["ROPS","cintura","attrezzo","PTO","pendenza","velocità","passeggeri","parcheggio"]'::jsonb,'["cintura non usata con ROPS","intervento vicino PTO in movimento","trasporto passeggero non previsto","trasversale su pendenza incompatibile"]'::jsonb,'["ROPS/ritenuta inefficiente","protezione PTO assente","pendenza/terreno non sicuri","attrezzo non correttamente collegato"]'::jsonb,'[{"kind":"reference","title":"INAIL - sicurezza in agricoltura","url":"https://www.inail.it/portale/ricerca-e-tecnologia/it/ambiti-di-ricerca/area-sicurezza-sul-lavoro/agricoltura.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/ricerca-e-tecnologia/it/ambiti-di-ricerca/area-sicurezza-sul-lavoro/agricoltura.html"}]'::jsonb,true)
