insert into public.course_scenarios_v22(course_id,scenario_id,position,required,context)
select c.id,s.id,2,true,jsonb_build_object('assigned_by','v22_003','specific',true,'equipment_specific',true,'update_course',m.is_update)
from map m join public.courses c on c.stable_key=m.course_key join public.training_scenarios_v22 s on s.stable_key=m.scenario_key
where c.active and coalesce(c.metadata->>'freeze_scope','')=''
on conflict(course_id,scenario_id) do update set position=excluded.position,required=true,context=excluded.context;

